    sx, sy = pos(od.get("self_position", (0, 0)), (0, 0))
    ox, oy = pos(od.get("opponent_position", (sx, sy)), (sx, sy))
    w = od.get("grid_width", 0) or 0
    h = od.get("grid_height", 0) or 0

    def cells_from_keys(keys):
        for k in keys:
            v = od.get(k, [])
            if v:
                return v
        return []

    def nearest(cells, ref):
        best = None
        best_d = None
        for c in cells:
            p = pos(c, None)
            if p is None:
                continue
            d = manhattan(p, ref)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(cells, ref):
        best = None
        best_d = None
