        if target is None:
            target = (sx - sgn(ox - sx), sy - sgn(oy - sy))
        return clamp_move((sx, sy), target)

    if env == "territory_control":
        # Prefer immediate strategic cells: frontier > unclaimed > opponent territory > any target
        frontier = cells_from_keys(("frontier_cells", "border_cells", "attack_frontier"))
        unclaimed = cells_from_keys(("unclaimed_cells", "neutral_cells", "empty_cells"))
        enemy = cells_from_keys(("opponent_territory", "enemy_territory", "enemy_cells"))
        targets = cells_from_keys(("target_cells", "objective_cells", "capture_cells"))

