            if p is not None:
                return clamp_move((sx, sy), p)

        # If no explicit map info, move toward opponent if behind, otherwise drift to center-ish.
        if (ox, oy) != (sx, sy):
            return [sgn(ox - sx), sgn(oy - sy)]
        if w > 0 and h > 0:
            return clamp_move((sx, sy), (w // 2, h // 2))
        return [0, 0]

