        best = None
        best_score = None
        for c in resources:
            p = pos(c, None)
            if p is None:
                continue
            d_self = manhattan(p, (sx, sy))
            d_opp = manhattan(p, (ox, oy))
            score = d_self * 2 - d_opp
            if best is None or score < best_score:
                best = p
                best_score = score
        if best is not None:
            return clamp_move((sx, sy), best)

    # Teamplay / avoidance / generic pursuit
    allies = cells_from_keys(("allied_positions", "teammate_positions", "ally_positions", "friends"))
